    };
};

fn find_duplicates<T: Eq + std::hash::Hash + Clone>(items: &[T]) -> Vec<T> {
    let mut seen = std::collections::HashSet::new();
    let mut duplicates = Vec::new();
    for item in items {
        if !seen.insert(item.clone()) {
            duplicates.push(item.clone());
        }
    }
    duplicates
}

class TrieNode:
    def __init__(self):
        self.children = {}
        self.is_end = False

class Trie:
    def __init__(self):
        self.root = TrieNode()
    def insert(self, word):
        node = self.root
        for ch in word:
            if ch not in node.children:
                node.children[ch] = TrieNode()
            node = node.children[ch]
        node.is_end = True
    def search(self, word):
        node = self.root
        for ch in word:
            if ch not in node.children:
                return False
            node = node.children[ch]
        return node.is_end

use std::collections::VecDeque;
struct SlidingWindow {
    data: VecDeque<i32>,
    sum: i64,
    size: usize,
}
impl SlidingWindow {
    fn new(size: usize) -> Self {
        Self { data: VecDeque::new(), sum: 0, size }
    }
    fn add(&mut self, value: i32) -> Option<f64> {
        self.data.push_back(value);
        self.sum += value as i64;
        if self.data.len() > self.size {
            self.sum -= self.data.pop_front().unwrap() as i64;
        }
        if self.data.len() == self.size {
            Some(self.sum as f64 / self.size as f64)
        } else {
            None
        }
    }
}
